  "implementation": "def solve(case):
    nodes = case['nodes']
    threshold = case['utility_threshold']
    node_dict = {n['id']: n for n in nodes}
    removed = set()
    # Initialize queue: descending depth, then stable by id (ascending)
    queue = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    queue = [n['id'] for n in queue]
    visit_order = []
    i = 0
    while i < len(queue):
        current_id = queue[i]
        i += 1
        visit_order.append(current_id)
        if current_id in removed:
            continue
        node = node_dict[current_id]
        # Leaf check: no child that is not removed
        is_leaf = True
        for other in nodes:
            if other['parent'] == current_id and other['id'] not in removed:
                is_leaf = False
                break
        if node['removable'] and is_leaf and node['utility'] <= threshold:
            removed.add(current_id)
            parent_id = node.get('parent')
            if parent_id is not None and parent_id not in removed and parent_id in node_dict:
                queue.append(parent_id)
    retained = [n['id'] for n in nodes if n['id'] not in removed]
    return {'retained_node_ids': retained, 'visit_order': visit_order}
